<?php require_once 'functions.php';require_login();$pageTitle='Food Dashboard';$s=db()->query('SELECT COUNT(*) c,COALESCE(SUM(quantity),0) q FROM stocks')->fetch();$sales=db()->query('SELECT COALESCE(SUM(quantity*price),0) t FROM billings')->fetchColumn();$history=db()->query('SELECT name,SUM(quantity*price) total FROM billings GROUP BY name ORDER BY total DESC')->fetchAll();$low=low_stocks();$all=stocks();require 'partials/header.php'; ?><div class="dashboard-page"><h1>Food Inventory Dashboard</h1><div class="metric-grid"><div class="metric-card">Total stock items<strong><?=e($s['c'])?></strong></div><div class="metric-card">Total quantity<strong><?=e($s['q'])?></strong></div><div class="metric-card">Total sales<strong>₹<?=number_format((float)$sales,2)?></strong></div><div class="metric-card">Low-stock items<strong><?=count($low)?></strong></div></div><div class="dashboard-grid"><section class="dashboard-card dashboard-graph"><h2>Sales Overview</h2><div class="chartbox"><canvas id="salesChart"></canvas></div></section><aside class="dashboard-right"><div class="dashboard-card"><h2>Notifications</h2><?php foreach(array_slice(alerts(),0,8) as $a):?><p class="notification-item"><?=e($a['message'])?></p><?php endforeach;?><a class="btn" href="notifications.php">View all</a></div><div class="dashboard-card dashboard-billing"><a class="billing-button" href="billing.php">Go to Billing</a></div></aside></div><div class="panel"><h2>Current Stock Levels</h2><div class="chartbox"><canvas id="stockChart"></canvas></div></div></div><script>new Chart(document.getElementById('salesChart'),{type:'bar',data:{labels:<?=json_encode(array_column($history,'name'))?>,datasets:[{label:'₹ Total Sales',data:<?=json_encode(array_map('floatval',array_column($history,'total')))?>,backgroundColor:'#FF69B4'}]},options:{responsive:true}});new Chart(document.getElementById('stockChart'),{type:'bar',data:{labels:<?=json_encode(array_column($all,'name'))?>,datasets:[{label:'Quantity',data:<?=json_encode(array_map('intval',array_column($all,'quantity')))?>,backgroundColor:'#FF69B4'}]},options:{responsive:true}});</script><?php require 'partials/footer.php'; ?>